package kvhttp

import java.io.OutputStream

/** The parts of a request head the server cares about. */
class RequestHead(
    val method: String,
    val target: String,
    /** Declared body length, or 0 when the request carries no `Content-Length`. */
    val contentLength: ULong,
)

sealed interface ParseResult {
    class Ok(val head: RequestHead) : ParseResult
    class Error(val status: Int) : ParseResult
}

class Response(
    val status: Int,
    val body: ByteArray = EMPTY,
    val contentType: String? = null,
    val allow: String? = null,
) {
    fun writeTo(out: OutputStream) {
        val head = buildString {
            append("HTTP/1.1 ").append(status).append(' ').append(reasonPhrase(status)).append("\r\n")
            append("Content-Length: ").append(body.size).append("\r\n")
            append("Connection: close\r\n")
            contentType?.let { append("Content-Type: ").append(it).append("\r\n") }
            allow?.let { append("Allow: ").append(it).append("\r\n") }
            append("\r\n")
        }
        out.write(head.toByteArray(Charsets.ISO_8859_1))
        if (body.isNotEmpty()) out.write(body)
        out.flush()
    }

    companion object {
        private val EMPTY = ByteArray(0)

        fun empty(status: Int) = Response(status)

        fun text(status: Int, text: String) =
            Response(status, text.toByteArray(Charsets.UTF_8), contentType = "text/plain; charset=utf-8")

        fun methodNotAllowed(allow: String) = Response(405, allow = allow)
    }
}

fun reasonPhrase(status: Int): String = when (status) {
    200 -> "OK"
    201 -> "Created"
    204 -> "No Content"
    400 -> "Bad Request"
    404 -> "Not Found"
    405 -> "Method Not Allowed"
    408 -> "Request Timeout"
    413 -> "Content Too Large"
    431 -> "Request Header Fields Too Large"
    500 -> "Internal Server Error"
    501 -> "Not Implemented"
    505 -> "HTTP Version Not Supported"
    else -> "Unknown"
}

private const val CR = '\r'.code.toByte()
private const val LF = '\n'.code.toByte()
private const val SP = ' '.code.toByte()
private const val COLON = ':'.code.toByte()
private const val TCHAR_SYMBOLS = "!#$%&'*+-.^_`|~"

private fun isTchar(b: Byte): Boolean {
    val c = (b.toInt() and 0xFF).toChar()
    return c in 'A'..'Z' || c in 'a'..'z' || c in '0'..'9' || c in TCHAR_SYMBOLS
}

private fun isOws(b: Byte): Boolean = b == SP || b == '\t'.code.toByte()

private fun ByteArray.indexOf(b: Byte, from: Int, to: Int): Int {
    for (i in from until to) if (this[i] == b) return i
    return -1
}

private fun ByteArray.latin1(from: Int, to: Int) = String(this, from, to - from, Charsets.ISO_8859_1)

private fun ByteArray.regionEqualsIgnoreCase(from: Int, to: Int, name: String): Boolean =
    to - from == name.length && latin1(from, to).equals(name, ignoreCase = true)

/** A non-empty run of ASCII digits that fits in an unsigned 64-bit integer. */
private fun parseSize(s: String): ULong? =
    if (s.isNotEmpty() && s.all { it in '0'..'9' }) s.toULongOrNull() else null

/**
 * Parses the request head in `buf[0, len)`, which excludes the terminating CRLFCRLF.
 */
fun parseHead(buf: ByteArray, len: Int): ParseResult {
    val lineEnd = buf.indexOf(CR, 0, len).let { if (it < 0) len else it }

    // Request line: method SP target SP version
    val sp1 = buf.indexOf(SP, 0, lineEnd)
    if (sp1 <= 0) return ParseResult.Error(400)
    val sp2 = buf.indexOf(SP, sp1 + 1, lineEnd)
    if (sp2 < 0 || sp2 == sp1 + 1) return ParseResult.Error(400)
    for (i in 0 until sp1) if (!isTchar(buf[i])) return ParseResult.Error(400)
    val version = buf.latin1(sp2 + 1, lineEnd)
    if (version.length != 8 || !version.startsWith("HTTP/1.")) {
        return ParseResult.Error(if (version.startsWith("HTTP/")) 505 else 400)
    }
    val method = buf.latin1(0, sp1)
    val target = buf.latin1(sp1 + 1, sp2)

    // Header fields
    var contentLength: ULong? = null
    var chunked = false
    var p = lineEnd
    while (p < len) {
        if (len - p < 2 || buf[p] != CR || buf[p + 1] != LF) return ParseResult.Error(400)
        p += 2
        val eol = buf.indexOf(CR, p, len).let { if (it < 0) len else it }
        val colon = buf.indexOf(COLON, p, eol)
        if (colon <= p) return ParseResult.Error(400)
        for (i in p until colon) if (!isTchar(buf[i])) return ParseResult.Error(400)

        var valueStart = colon + 1
        var valueEnd = eol
        while (valueStart < valueEnd && isOws(buf[valueStart])) valueStart++
        while (valueEnd > valueStart && isOws(buf[valueEnd - 1])) valueEnd--

        when {
            buf.regionEqualsIgnoreCase(p, colon, "Content-Length") -> {
                val cl = parseSize(buf.latin1(valueStart, valueEnd)) ?: return ParseResult.Error(400)
                if (contentLength != null && contentLength != cl) return ParseResult.Error(400)
                contentLength = cl
            }
            buf.regionEqualsIgnoreCase(p, colon, "Transfer-Encoding") -> chunked = true
        }
        p = eol
    }

    if (chunked) return ParseResult.Error(if (contentLength != null) 400 else 501)
    return ParseResult.Ok(RequestHead(method, target, contentLength ?: 0u))
}

package kvhttp

import java.util.concurrent.ConcurrentHashMap

/**
 * Thread-safe in-memory key-value store. Values are arbitrary byte sequences.
 *
 * Stored arrays are never mutated after insertion, so they can be handed out
 * to readers without copying.
 */
class KvStore {
    private val entries = ConcurrentHashMap<String, ByteArray>()

    /** Stores [value] under [key]; returns `true` if the key was new, `false` if it replaced a value. */
    fun put(key: String, value: ByteArray): Boolean = entries.put(key, value) == null

    fun get(key: String): ByteArray? = entries[key]

    /** Returns `true` if the key was present and has been removed. */
    fun delete(key: String): Boolean = entries.remove(key) != null

    /** A snapshot of all keys, sorted ascending. */
    fun sortedKeys(): List<String> = entries.keys.sorted()
}

package kvhttp

import java.io.IOException
import kotlin.system.exitProcess

fun main(args: Array<String>) {
    if (args.size != 1) {
        System.err.println("usage: app <port>")
        exitProcess(2)
    }
    val port = args[0].takeIf { s -> s.all { it.isDigit() } }?.toIntOrNull()?.takeIf { it in 1..65535 }
    if (port == null) {
        System.err.println("invalid port: ${args[0]}")
        exitProcess(2)
    }
    try {
        KvServer().serve(port)
    } catch (e: IOException) {
        System.err.println("listen: ${e.message}")
        exitProcess(1)
    }
}

package kvhttp

import java.io.BufferedOutputStream
import java.io.IOException
import java.io.InputStream
import java.io.OutputStream
import java.net.InetAddress
import java.net.InetSocketAddress
import java.net.ServerSocket
import java.net.Socket
import java.net.SocketTimeoutException
import java.util.concurrent.Executors

private const val MAX_HEADER_BYTES = 16 * 1024
private const val MAX_KEY_LEN = 64
private const val MAX_VALUE_BYTES = 1L shl 20
private const val IO_TIMEOUT_MS = 10_000
private const val DRAIN_LIMIT = 4 * 1024 * 1024
private val HEAD_TERMINATOR = "\r\n\r\n".toByteArray(Charsets.ISO_8859_1)

/**
 * A minimal HTTP/1.1 key-value server: one virtual thread per connection,
 * one request per connection.
 */
class KvServer(private val store: KvStore = KvStore()) {

    fun serve(port: Int) {
        ServerSocket().use { listener ->
            listener.reuseAddress = true
            listener.bind(InetSocketAddress(InetAddress.getLoopbackAddress(), port), 1024)
            Executors.newVirtualThreadPerTaskExecutor().use { executor ->
                while (true) {
                    val socket = try {
                        listener.accept()
                    } catch (e: IOException) {
                        System.err.println("accept: ${e.message}")
                        Thread.sleep(10) // resource pressure: back off briefly
                        continue
                    }
                    executor.execute { handle(socket) }
                }
            }
        }
    }

    private fun handle(socket: Socket) {
        try {
            socket.soTimeout = IO_TIMEOUT_MS
            socket.tcpNoDelay = true
            val input = socket.getInputStream()
            val output = BufferedOutputStream(socket.getOutputStream(), 64 * 1024)
            serveConnection(input, output)
            lingeringClose(socket, input)
        } catch (_: IOException) {
            // Client went away or timed out; nothing more to do.
        } finally {
            socket.close()
        }
    }

    /**
     * Half-closes and drains whatever the peer still sends, so that closing the
     * socket does not reset the connection before the client reads the reply.
     */
    private fun lingeringClose(socket: Socket, input: InputStream) {
        socket.shutdownOutput()
        val sink = ByteArray(4096)
        var total = 0
        while (total < DRAIN_LIMIT) {
            val n = input.read(sink)
            if (n <= 0) break
            total += n
        }
    }

    private fun serveConnection(input: InputStream, output: OutputStream) {
        val buf = ByteArray(MAX_HEADER_BYTES)
        var used = 0
        var headEnd = -1

        while (headEnd < 0) {
            if (used == MAX_HEADER_BYTES) {
                Response.empty(431).writeTo(output)
                return
            }
            val n = try {
                input.read(buf, used, MAX_HEADER_BYTES - used)
            } catch (_: SocketTimeoutException) {
                if (used > 0) Response.empty(408).writeTo(output)
                return
            }
            if (n <= 0) return
            val from = maxOf(used - 3, 0)
            used += n
            headEnd = buf.indexOf(HEAD_TERMINATOR, from, used)
            // Embedded NULs are never valid in a request head.
            val scanEnd = if (headEnd < 0) used else headEnd
            if ((from until scanEnd).any { buf[it] == 0.toByte() }) {
                Response.empty(400).writeTo(output)
                return
            }
        }

        when (val parsed = parseHead(buf, headEnd)) {
            is ParseResult.Error -> Response.empty(parsed.status).writeTo(output)
            is ParseResult.Ok -> {
                val bodyStart = headEnd + HEAD_TERMINATOR.size
                val prefix = buf.copyOfRange(bodyStart, used)
                route(parsed.head, BodyReader(prefix, input))?.writeTo(output)
            }
        }
    }

    /** Returns the response to send, or `null` if the connection should just be closed. */
    private fun route(head: RequestHead, body: BodyReader): Response? {
        val method = head.method
        val target = head.target
        return when {
            target == "/health" ->
                if (method == "GET") Response.text(200, "ok") else Response.methodNotAllowed("GET")

            target == "/kv" ->
                if (method == "GET") listKeys() else Response.methodNotAllowed("GET")

            target.startsWith("/kv/") -> {
                val key = target.substring(4)
                when {
                    !isValidKey(key) -> Response.empty(400)
                    method == "GET" -> getValue(key)
                    method == "PUT" -> putValue(key, head.contentLength, body)
                    method == "DELETE" -> Response.empty(if (store.delete(key)) 204 else 404)
                    else -> Response.methodNotAllowed("GET, PUT, DELETE")
                }
            }

            else -> Response.empty(404)
        }
    }

    private fun listKeys(): Response {
        // Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is required.
        val json = store.sortedKeys().joinToString(",", "[", "]") { "\"$it\"" }
        return Response(200, json.toByteArray(Charsets.US_ASCII), contentType = "application/json")
    }

    private fun getValue(key: String): Response {
        val value = store.get(key) ?: return Response.empty(404)
        return Response(200, value, contentType = "application/octet-stream")
    }

    private fun putValue(key: String, contentLength: ULong, body: BodyReader): Response? {
        if (contentLength > MAX_VALUE_BYTES.toULong()) return Response.empty(413)
        val value = body.readExactly(contentLength.toInt()) ?: return null
        return Response.empty(if (store.put(key, value)) 201 else 200)
    }
}

/** Reads a request body, starting with bytes that arrived together with the head. */
private class BodyReader(private val prefix: ByteArray, private val input: InputStream) {
    /** Reads exactly [len] bytes; returns `null` on EOF before that. */
    fun readExactly(len: Int): ByteArray? {
        val data = ByteArray(len)
        val have = minOf(prefix.size, len)
        prefix.copyInto(data, endIndex = have)
        return if (input.readNBytes(data, have, len - have) == len - have) data else null
    }
}

fun isValidKey(key: String): Boolean =
    key.length in 1..MAX_KEY_LEN &&
        key.all { it in 'A'..'Z' || it in 'a'..'z' || it in '0'..'9' || it == '_' || it == '-' }

private fun ByteArray.indexOf(needle: ByteArray, from: Int, to: Int): Int {
    outer@ for (i in from..to - needle.size) {
        for (j in needle.indices) if (this[i + j] != needle[j]) continue@outer
        return i
    }
    return -1
}
